'use strict';
(()=>{
const Q=id=>document.getElementById(id),C=PlannerCore,B=BrowseCore,all=LA_DATA.events,by=new Map(all.map(e=>[e.id,e])),days=LA_DATA.days;
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=s=>/^https?:\/\//i.test(s||'')?safe(s):'#';
const clock=s=>s?new Date(s).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/Los_Angeles'}):'End unknown';
const dayname=d=>new Date(d+'T12:00:00-07:00').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',timeZone:'America/Los_Angeles'});
const area=e=>B.label(e)+(B.isLA(e)&&B.neighborhoods(e).length?' / '+B.neighborhoods(e).join(' / '):'');
let selectedDays=new Set([days[0]]);
let saved=new Set(),tab='discover',day=days[0],preset='all',limit=35,anchor=null,fieldPlan=false,chosen=null,timer=null,restored=false,lastHour=null,draft=null,draftVariant=0;
try{const a=JSON.parse(localStorage.getItem('fieldtrip-la-2026')||'[]');if(Array.isArray(a))saved=new Set(a.filter(id=>by.has(id)));}catch{}
const corpus=new Map(all.map(e=>[e.id,[e.name,...e.hosts,...e.themes,...e.formats,...e.areas,...(e.publicAddress||[]),B.label(e),e.description].join(' ').toLowerCase()]));
const presets={all:()=>true,build:e=>e.formats.some(t=>/workshop|hackathon|demo/i.test(t))||e.themes.some(t=>/developer|infrastructure|deep tech/i.test(t)),capital:e=>e.themes.includes('Fundraising / Investing'),creative:e=>e.themes.some(t=>/creator|entertainment|design|gaming/i.test(t)),social:e=>e.formats.some(t=>/happy hour|party|networking/i.test(t))};
function toast(s){Q('toast').textContent=s;Q('toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>Q('toast').hidden=true,3500);}
function setOptions(id,values){Q(id).insertAdjacentHTML('beforeend',[...new Set(values)].sort().map(t=>`<option value="${safe(t)}">${safe(t)}</option>`).join(''));}
setOptions('topic-filter',all.flatMap(e=>e.themes));Q('place-filter').innerHTML='<option value="">All places</option>'+B.placeGroups(all).map(g=>`<optgroup label="${safe(g.label)}">${g.options.map(o=>`<option value="${safe(o.value)}">${safe(o.label)}</option>`).join('')}</optgroup>`).join('');setOptions('format-filter',all.flatMap(e=>e.formats));
function matching(ignoreDay=false,ignoreHour=false){const hour=fieldHost.get().hour;const query=Q('query').value.toLowerCase().trim().split(/\s+/).filter(Boolean),topic=Q('topic-filter').value,place=Q('place-filter').value,format=Q('format-filter').value;
let rows=all.filter(e=>(ignoreHour||hour===null||C.activeHour(e,hour))&&(ignoreDay||[...selectedDays].some(d=>C.activeDay(e,d)))&&presets[preset](e)&&(!topic||e.themes.includes(topic))&&B.matchesPlace(e,place)&&(!format||e.formats.includes(format))&&(!Q('hide-closed').checked||e.registration!=='closed')&&query.every(t=>corpus.get(e.id).includes(t)));
if(anchor){const fits=C.nextFit(by.get(anchor),rows);rows=fits.map(x=>x.e);}else{const sort=Q('sort-filter').value;rows.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='featured'?Number(b.featured)-Number(a.featured)||C.start(a)-C.start(b):C.start(a)-C.start(b)||a.name.localeCompare(b.name));}return rows;}
function row(e,plan=false){return `<article class="event-row" data-row="${safe(e.id)}"><button class="event-open" data-open="${safe(e.id)}"><span class="when">${safe(dayname(e.date))} · ${safe(clock(e.startsAt))}${e.featured?' · ✦ FEATURED':''}</span><strong>${safe(e.name)}</strong><span class="where">${safe(area(e))} · ${safe(e.hosts.join(' / '))}</span><span class="tagline">${e.registration==='closed'?'Registration closed':C.multi(e)?'Multiple days · check individual sessions':e.access==='APPLY'?'Application required':safe(e.formats[0]||'Event')}${!e.endsAt?' · End time not published':''}</span></button><button class="save ${saved.has(e.id)?'saved':''}" data-save="${safe(e.id)}" aria-label="${saved.has(e.id)?'Remove':'Save'} ${safe(e.name)}" aria-pressed="${saved.has(e.id)}">${saved.has(e.id)?'✓':'+'}</button>${plan?`<div style="grid-column:1/-1"><a class="print-only" href="${url(e.partiful||e.official)}">${safe(e.partiful||e.official)}</a></div>`:''}</article>`;}
function paintWeek(){const candidates=fieldPlan?[...saved].map(id=>by.get(id)):matching(true,true);
if(!Q('week-strip').children.length){Q('week-strip').innerHTML=days.map((d,i)=>`<label class="day-check"><span>${['MON','TUE','WED','THU','FRI','SAT','SUN'][i]}</span><input type="radio" name="cartographer-day" data-week-day="${d}" aria-label="${safe(dayname(d))}"><b>${12+i}</b><small data-week-count="${d}"></small></label>`).join('');}
for(const d of days){document.querySelector(`[data-week-day="${d}"]`).checked=d===day;document.querySelector(`[data-week-count="${d}"]`).textContent=candidates.filter(e=>C.activeDay(e,d)).length+' events';}}
function syncDays(){day=selectedDays.size===1?[...selectedDays][0]:'';fieldHost.days([...selectedDays]);anchor=null;limit=35;render();}
Q('week-strip').addEventListener('change',e=>{const d=e.target.dataset.weekDay;if(!d)return;selectedDays=new Set([d]);syncDays();});

function render(){const rows=matching();Q('results').innerHTML=rows.length?rows.slice(0,limit).map(e=>row(e)).join(''):'<div class="empty"><b>A little too specific?</b>Try another day or reset your filters.</div>';Q('result-count').textContent=`${rows.length} possibilities`;Q('load-more').hidden=rows.length<=limit;Q('next-context').hidden=!anchor;if(anchor)Q('next-context').innerHTML=`AFTER <b>${safe(by.get(anchor).name)}</b><br>30 min–4 hours later. Shared areas and topics first. Travel time still needs checking.<button id="exit-next">Back to all events</button>`;
fieldHost.filter(fieldPlan?[...saved]:matching(false,true).map(e=>e.id));fieldHost.saved([...saved]);Q('saved-count').textContent=Q('plan-count').textContent=saved.size;paintWeek();paintPlan();updateFieldStatus();}
function setTab(t){tab=t;Q('discovery').hidden=t!=='discover';Q('itinerary').hidden=t!=='plan';Q('discover-tab').setAttribute('aria-pressed',String(t==='discover'));Q('itinerary-tab').setAttribute('aria-pressed',String(t==='plan'));if(t==='discover')fieldPlan=false;render();}
function toggleSave(id){saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('fieldtrip-la-2026',JSON.stringify([...saved]));}catch{toast('Browser storage unavailable. Export your plan before closing.');}render();if(chosen===id&&Q('event-modal').open)paintDetail(id);}
function paintPlan(){const es=[...saved].map(id=>by.get(id)).sort((a,b)=>C.start(a)-C.start(b)),warn=C.warnings(es);for(const id of ['export-calendar','print-plan','show-plan-field'])Q(id).disabled=!es.length;Q('show-plan-field').textContent=fieldPlan?'Show all events':'Show in field';if(!es.length){Q('plan-list').innerHTML='<div class="empty"><b>Start with one good thing.</b>Tap + on an event. Your plan will appear here, and trace a path through the 3D week.<br><button id="empty-discover" class="next-button">Find your first event ↗</button></div>';return;}
let lastDay='',html='';for(let i=0;i<es.length;i++){const e=es[i],prev=es[i-1];if(e.date!==lastDay){html+=`<h3 class="plan-day">${safe(dayname(e.date))}</h3>`;lastDay=e.date;}html+=row(e,true);for(const w of warn.get(e.id))html+=`<div class="conflict">↔ ${safe(w)}</div>`;
if(!e.endsAt)html+='<div class="conflict">End time unknown — check the host before fitting another event afterward.</div>';else if(C.multi(e))html+='<div class="gap">Multi-day listing: confirm individual sessions with the host. Not treated as one continuous booking.</div>';
if(prev&&prev.date===e.date&&!C.multi(prev)&&!C.multi(e)&&C.end(prev)!==null&&C.start(e)>=C.end(prev)){const minutes=Math.round((C.start(e)-C.end(prev))/60000);html+=`<div class="${minutes<30?'conflict':'gap'}">${minutes} min after the previous event. ${minutes<30?'Tight changeover. ':''}${prev.municipality!==e.municipality?'Different areas — check travel.':'Check venue and travel time.'}</div>`;}
if(e.endsAt&&!C.multi(e))html+=`<button class="next-button" data-next="${e.id}">Find something after this ↗</button>`;}
Q('plan-list').innerHTML=html;}
function paintDetail(id){const e=by.get(id);if(!e)return;chosen=id;fieldHost.select(id);fieldHost.stop();const exact=Boolean(e.geocode),precision=exact?'Approximate public address':e.neighborhoodGeocode?'Approximate neighborhood':e.coords?'City-level location':'Location unknown / virtual';
Q('event-content').innerHTML=`<span class="eyebrow">${safe(dayname(e.date))} / ${safe(clock(e.startsAt))} PT</span><h2 class="modal-title">${safe(e.name)}</h2><div class="event-meta">${safe(e.hosts.join(' / '))}<br>${safe(area(e))} · ${e.endsAt?safe(clock(e.startsAt)+'–'+clock(e.endsAt)):safe(clock(e.startsAt))+' · End not published'}${C.multi(e)?' · through '+safe(dayname(e.endDate)):''}<br>${e.registration==='closed'?'Registration closed':e.access==='APPLY'?'Application required · admission not guaranteed':'Check host for admission and availability'}</div><div class="detail-tags">${[...e.themes,...e.formats].map(t=>`<span>${safe(t)}</span>`).join('')}</div><div class="detail-actions"><button data-save="${safe(id)}">${saved.has(id)?'✓ Saved to my week':'+ Save to my week'}</button><a href="${url(e.partiful||e.official)}" target="_blank" rel="noopener">Check event / RSVP ↗</a>${e.endsAt&&!C.multi(e)?`<button data-next="${safe(id)}">What fits after? ↗</button>`:''}</div><p class="source-note">${precision}. ${e.publicAddress?.length?safe(e.publicAddress.join(', ')):safe(e.locationBasis)}<br>Schedule checked October 10. Description ${e.descriptionDate==='2026-10-10'?'checked October 10':'from October 7'}; verify current venue and availability with the host.${e.sourceConflict?'<br>Earlier sources disagreed on time. This view uses the current official schedule.':''}</p><div class="description">${safe(e.description)}</div>${e.applicationQuestions?.length?`<details><summary>Application questions from October 7</summary><div class="description">${safe(e.applicationQuestions.map(x=>typeof x==='string'?x:x.title||x.question||x.label||'See host application').join('\n\n'))}</div></details>`:''}<p class="source-note"><a href="${url(e.official)}" target="_blank" rel="noopener">Official source ↗</a> · Saved events are possibilities, not confirmed attendance.</p>`;
}
function openDetail(id){paintDetail(id);Q('event-modal').showModal();}
function next(id){const e=by.get(id);if(!e.endsAt||C.multi(e)){toast('Check the session end time with the host first.');return;}reset(false);anchor=id;day=e.endDate;selectedDays=new Set([day]);fieldHost.days([...selectedDays]);Q('event-modal').close();setTab('discover');Q('discovery').scrollIntoView({block:'nearest',behavior:'smooth'});}
function reset(paint=true){day=day||days[0];selectedDays=new Set([day]);anchor=null;preset='all';fieldPlan=false;limit=35;for(const id of ['query','topic-filter','place-filter','format-filter'])Q(id).value='';Q('sort-filter').value='time';Q('hide-closed').checked=false;document.querySelectorAll('[data-preset]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.preset==='all')));fieldHost.day(day);if(paint)render();}
function showDraft(){
 fieldHost.stop();draft=C.assemble(matching(false,true),day,draftVariant);
 Q('draft-content').innerHTML=draft.events.length?`<span class="eyebrow">A POSSIBLE DAY / ${safe(dayname(draft.day))}</span><h2 class="modal-title">${safe(draft.area)}.<br>See where it takes you.</h2><p class="source-note">${draft.events.length} stops with published end times, in the same listed area. At least 45 minutes between events. Check exact venues, travel and admission before committing.</p><div class="draft-stops">${draft.events.map((e,i)=>`<article><span class="stop-number">0${i+1}</span><div><span class="source-note">${safe(clock(e.startsAt))}—${safe(clock(e.endsAt))}</span><h3>${safe(e.name)}</h3><p>${safe(e.formats.join(' · '))}</p><a href="${url(e.partiful||e.official)}" target="_blank" rel="noopener">Check event ↗</a></div></article>`).join('')}</div><div class="detail-actions"><button id="draft-save">+ Add this day to my week</button><button id="draft-reroll">Another combination ↻</button></div><p class="source-note">A draft based on your filters, matching area labels, known times and format variety. Not personalized advice or confirmed bookings. Unknown-duration and multi-day listings stay available in Discover.</p>`:'<span class="eyebrow">LET’S LOOSEN THE PLAN</span><h2 class="modal-title">Not enough information<br>to assemble this day.</h2><p class="source-note">Try another day or broader interests. Events without published end times are still in Discover, but we won’t invent a schedule around them.</p>';
}
function updateFieldStatus(){const f=fieldHost.get();if(lastHour!==f.hour){lastHour=f.hour;render();return;}Q('new-3d').setAttribute('aria-pressed',String(f.mode==='stack'));Q('new-map').setAttribute('aria-pressed',String(f.mode==='map'));Q('field-help').textContent=f.mode==='stack'?(innerWidth<761?'Drag to look · + / − to fly · Tap a point':'Drag to look · Scroll to fly · Click a point'):'Drag to pan · Scroll to zoom · Click a point';Q('field-count').textContent=Q('visible-count').textContent;Q('new-watch').textContent=f.watching?'Ⅱ Pause the week':'▷ Watch the week';Q('new-watch').setAttribute('aria-pressed',String(f.watching));Q('scrub-label').textContent=f.hour===null?'ALL HOURS':['MON','TUE','WED','THU','FRI','SAT','SUN'][Math.floor(f.hour/24)]+' '+String(f.hour%24).padStart(2,'0')+':00 PT';if(f.hour!==null)Q('new-scrub').value=f.hour;}
document.addEventListener('click',ev=>{const el=ev.target.closest('button');if(!el)return;if(el.dataset.open)openDetail(el.dataset.open);if(el.dataset.save)toggleSave(el.dataset.save);if(el.dataset.next)next(el.dataset.next);if(el.id==='exit-next')reset();if(el.id==='empty-discover')setTab('discover');if(el.id==='draft-reroll'){draftVariant++;showDraft();}if(el.id==='draft-save'){for(const e of draft.events)saved.add(e.id);try{localStorage.setItem('fieldtrip-la-2026',JSON.stringify([...saved]));}catch{toast('Export your plan before closing; browser storage is unavailable.');}Q('draft-modal').close();setTab('plan');toast('Day added. Check the host pages to RSVP.');}if(el.dataset.day!==undefined){day=el.dataset.day;anchor=null;limit=35;fieldHost.day(day);render();}if(el.dataset.preset){preset=el.dataset.preset;limit=35;anchor=null;document.querySelectorAll('[data-preset]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));render();}});
for(const id of ['query','topic-filter','place-filter','format-filter','sort-filter','hide-closed'])Q(id).addEventListener(id==='query'?'input':'change',()=>{limit=35;render();});
Q('clear-filters').onclick=()=>reset();Q('load-more').onclick=()=>{limit+=35;render();};Q('discover-tab').onclick=()=>setTab('discover');Q('itinerary-tab').onclick=()=>setTab('plan');Q('plan-toggle').onclick=()=>{setTab(tab==='plan'?'discover':'plan');Q('browser')?.scrollIntoView();if(innerWidth<761)document.querySelector('.browser').scrollIntoView({behavior:'smooth'});};Q('show-plan-field').onclick=()=>{selectedDays=new Set(days);fieldPlan=!fieldPlan;fieldHost.day('');day='';render();};Q('new-3d').onclick=()=>{fieldHost.view('stack');updateFieldStatus();};Q('new-map').onclick=()=>{fieldHost.view('map');updateFieldStatus();};Q('new-home').onclick=()=>fieldHost.home();Q('new-near').onclick=()=>fieldHost.zoom(1);Q('new-far').onclick=()=>fieldHost.zoom(-1);Q('new-watch').onclick=()=>{selectedDays=new Set(days);fieldHost.watch();day='';render();updateFieldStatus();};Q('new-scrub').oninput=()=>{selectedDays=new Set(days);day='';fieldHost.hour(Number(Q('new-scrub').value));updateFieldStatus();};Q('all-hours').onclick=()=>{fieldHost.days([...selectedDays]);updateFieldStatus();};
Q('draft-close').onclick=()=>Q('draft-modal').close();if(Q('assemble-day'))Q('assemble-day').onclick=()=>{draftVariant=0;showDraft();Q('draft-modal').showModal();};
Q('event-close').onclick=()=>Q('event-modal').close();Q('notes-close').onclick=()=>Q('notes-modal').close();for(const id of ['event-modal','notes-modal','draft-modal'])Q(id).addEventListener('click',e=>{if(e.target===Q(id)){const r=Q(id).getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)Q(id).close();}});
Q('event-modal').addEventListener('close',()=>{chosen=null;fieldHost.select(null);});
Q('data-info').onclick=()=>{fieldHost.stop();Q('notes-modal').showModal();};Q('notes-content').innerHTML=`<p><b>${all.length} official events.</b> The official schedule, names, topics, formats and registration labels were refreshed October 10. ${PLANNER_META.added} newly listed events were added; ${PLANNER_META.removed} no longer listed IDs remain in the original research, outside this view.</p><p>Most full descriptions, public host details and application questions come from October 7. The host’s event page is the place to check current admission, price and exact location. “Open” does not mean approved or free.</p><p><b>Space is approximate.</b> Published addresses use approximate street positions; other points use neighborhood or city centers. Gray points have no resolved location. Nearby in the field does not guarantee nearby venues. Lines joining your saved events show sequence, not roads or travel times.</p><p><b>Time is Pacific.</b> ${PLANNER_META.unknownEnds} events have no published end time. They appear at their start time, are flagged in your plan and are never given a made-up duration. Multi-day listings may represent recurring sessions; check with the host.</p><p>Gold dots are events. Larger dots retain the original October 7 editorial prominence estimate; new unscored events use the base size. Mint rings mark saved events. This is not a measured quality or attendance ranking.</p><p>Built with Prairie Labs’ Semantic Field Cartographer. Local geography from LA County, Census and <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors (ODbL)</a>. Your plan stays in this browser. No account required.</p>`;
Q('export-calendar').onclick=()=>{const events=[...saved].map(id=>by.get(id)).sort((a,b)=>C.start(a)-C.start(b)),blob=new Blob([C.ics(events)],{type:'text/calendar;charset=utf-8'}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download='fieldtrip-la-tech-week.ics';a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);toast('Calendar exported. Events are tentative; RSVP with each host.');};Q('print-plan').onclick=()=>{setTab('plan');window.print();};
window.addEventListener('field-select',e=>openDetail(e.detail));document.querySelector('.eyebrow').textContent=`${all.length} POSSIBILITIES. ONE YOU.`;
fieldHost.day(day);setInterval(updateFieldStatus,250);render();
window.Fieldtrip={add:ids=>{for(const id of ids)if(by.has(id))saved.add(id);try{localStorage.setItem('fieldtrip-la-2026',JSON.stringify([...saved]));}catch{toast('Export before closing; browser storage is unavailable.');}setTab('plan');toast('Added to your week. Check admission with each host.');},getState:()=>({saved:[...saved],days:[...selectedDays],day,preset,anchor,matching:matching().map(e=>e.id),field:fieldHost.get()}),open:openDetail};
if(location.hash.startsWith('#event=')){const id=decodeURIComponent(location.hash.slice(7));if(by.has(id))openDetail(id);}
})();
